SELECT AVG(distance_km) AS avg_distance_km
FROM rides
WHERE status = 'completed';

SELECT MAX(distance_km) AS longest_distance_km
FROM rides
WHERE status = 'completed';

SELECT COUNT(*) AS one_star_rating_count
FROM ratings
WHERE rating = 1;

SELECT COUNT(*) AS five_star_ratings_count
FROM ratings
WHERE rating = 5;

SELECT DISTINCT city
FROM users
WHERE user_type = 'driver';

SELECT COUNT(*) AS ride_count
FROM rides
WHERE surge_multiplier = 2;

SELECT AVG(rating) AS average_rating
FROM ratings
WHERE driver_id = 3156;

SELECT COUNT(*) AS vehicle_count
FROM vehicles
WHERE year <= 2018;

SELECT COUNT(*) AS ride_requests_2025
FROM rides
WHERE EXTRACT(YEAR FROM requested_at) = 2025;

SELECT COUNT(*) AS vehicle_count
FROM vehicles
WHERE year <= 2016;
